import{_ as a,o as t,c as r,a4 as i}from"./chunks/framework.CzJ_HCFe.js";const p=JSON.parse('{"title":"Trade-inventory purchase source profile","description":"","frontmatter":{},"headers":[],"relativePath":"reference/50-trade-inventory-purchase-profile.md","filePath":"reference/50-trade-inventory-purchase-profile.md","lastUpdated":1788720195000}'),n={name:"reference/50-trade-inventory-purchase-profile.md"};function s(o,e,d,l,u,c){return t(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="trade-inventory-purchase-source-profile" tabindex="-1">Trade-inventory purchase source profile <a class="header-anchor" href="#trade-inventory-purchase-source-profile" aria-label="Permalink to &quot;Trade-inventory purchase source profile&quot;">​</a></h1><h2 id="authorities-and-boundary" tabindex="-1">Authorities and boundary <a class="header-anchor" href="#authorities-and-boundary" aria-label="Permalink to &quot;Authorities and boundary&quot;">​</a></h2><p>The <code>business_inventory_purchase</code> activity implements B. V. Raman, <em>Muhurtha (Electional Astrology)</em>, Chapter X, “Buying for Business,” internal printed page 45 (physical PDF page 49 in the inspected 2020 Chistabo derivative). The act is purchasing stock, raw materials or goods for resale or business use.</p><p>Rama Daivajna&#39;s <em>Muhurta Chintamani</em>, Nakshatra-prakarana verse 16, printed pages 33–34 (OCR lines 2336–2350), independently distinguishes buyer-side purchase from seller-side timing. It supports the transaction-role boundary; it does not supply Raman&#39;s inventory-specific Thursday/Dashami/Pushya formula.</p><p>This profile is not an election for founding an enterprise, deploying capital, opening a marketplace, selling stock or making an ordinary consumer purchase.</p><h2 id="rule-crosswalk" tabindex="-1">Rule crosswalk <a class="header-anchor" href="#rule-crosswalk" aria-label="Permalink to &quot;Rule crosswalk&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Source statement</th><th>Product treatment</th></tr></thead><tbody><tr><td>Thursday, Dashami and Pushya are “best”</td><td>Three independent +1 preferences; none is made an exclusive gate</td></tr><tr><td>Tuesday should be completely rejected</td><td>Tuesday is the sole hard weekday exclusion</td></tr><tr><td>Saturday is passable</td><td>Saturday remains admissible without a bonus</td></tr><tr><td>Fortify Budha, the 2nd lord and the 2nd house</td><td>Manual prerequisite</td></tr><tr><td>Avoid Budha afflicted by Mangala</td><td>Manual prerequisite</td></tr><tr><td>Budha and Guru together in Lagna or mutual aspect are highly propitious</td><td>Manual prerequisite</td></tr></tbody></table><p>Treating “best” as “only” would invent a prohibition. A date can therefore survive without all three preferences, but the result cannot reach <code>Excellent</code> until the chart conditions have been reviewed.</p><h2 id="commercial-safety" tabindex="-1">Commercial safety <a class="header-anchor" href="#commercial-safety" aria-label="Permalink to &quot;Commercial safety&quot;">​</a></h2><p>Electional timing cannot establish demand, stock quality, supplier reliability, profitability or solvency. Commercial need, supplier terms, cash flow, tax and legal advice always take precedence.</p>',10)])])}const m=a(n,[["render",s]]);export{p as __pageData,m as default};
